DECLARE @custids VARCHAR(MAX),
	@ErrCode 	INT = 0 ,
	@ErrMsg		NVARCHAR(MAX) = '' 

SELECT @custids =stuff( (
SELECT ',' + CAST(custid AS VARCHAR(10))
FROM #tmpCust
WHERE isDep = 1
FOR XML PATH  (''))	,1,1,'' )

--remove PA for licensee
EXEC NAP_ProblemAccount_LicenseeRemoveCustomer
	@CustomerList = @custids,

	@UserID		= 8,
	@IP			= '',
	@ErrCode 	= @ErrCode OUTPUT,
	@ErrMsg		= @ErrMsg OUTPUT
	
SELECT @ErrCode, @ErrMsg



SELECT @custids =stuff( (
SELECT ',' + CAST(custid AS VARCHAR(10))
FROM #tmpCust
WHERE isDep = 0
FOR XML PATH  (''))	,1,1,'' )
	
--remove PA for credit
EXEC NAP_ProblemAccount_RemoveCustomer
	@CustomerList = @custids,
	@RoleId 	= 1,
	@ExcludeAbnormalMember = 0,
	@ExcludeDirectMark = 0,

	@UserID		= 8,
	@IP			= '',
	@ErrCode 	= @ErrCode OUTPUT,
	@ErrMsg		= @ErrMsg OUTPUT
	
SELECT @ErrCode, @ErrMsg